import { createHash } from 'node:crypto';
import type { PGlite } from '@electric-sql/pglite';
import { z } from 'zod';

const observationSchema = z.object({ schemaDigest: z.string(), serverVersion: z.string() });

export async function observeEnvironment(database: PGlite) {
  const result = await database.query<{ schemaDigest: string; serverVersion: string }>(`
    SELECT md5(string_agg(tablename, ',' ORDER BY tablename)) AS "schemaDigest",
           current_setting('server_version') AS "serverVersion"
    FROM pg_tables WHERE schemaname='public'
  `);
  return result.rows[0];
}

export function fingerprint(observation: unknown): string | null {
  return createHash('sha256').update(JSON.stringify(observationSchema.parse(observation))).digest('hex');
}

export async function validateSql(database: PGlite, cache: Map<string, true>, observation?: unknown) {
  const key = fingerprint(observation === undefined ? await observeEnvironment(database) : observation);
  if (key !== null && cache.has(key)) return { source: 'reused' as const };
  await database.query('SELECT count(*) FROM protected_probe');
  if (key !== null) cache.set(key, true);
  return { source: 'executed' as const };
}

