import { test, expect } from 'bun:test';
import { PGlite } from '@electric-sql/pglite';
import { validateSql } from '../src/sql-validation';

test('reuses a successful unchanged administrator validation', async () => {
  const database = new PGlite();
  try {
    await database.exec('CREATE TABLE protected_probe(id int)');
    const cache = new Map<string, true>();
    expect((await validateSql(database, cache)).source).toBe('executed');
    expect((await validateSql(database, cache)).source).toBe('reused');
  } finally {
    await database.close();
  }
});

