import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
import { pathToFileURL } from 'node:url';

const root = process.argv[2];
const require = createRequire(root + '/package.json');
const { PGlite } = await import(pathToFileURL(require.resolve('@electric-sql/pglite')).href);
const { fingerprint, observeEnvironment, validateSql } = await import(root + '/src/sql-validation.ts');
const outcomes: { name: string; pass: boolean; detail?: string }[] = [];
async function check(name: string, assertion: () => unknown | Promise<unknown>) {
  try {
    await assertion();
    outcomes.push({ name, pass: true });
  } catch (error) {
    if (!(error instanceof assert.AssertionError)) throw error;
    outcomes.push({ name, pass: false, detail: error.message });
  }
}
function noReusableFingerprint(observation: unknown) {
  let first: string | null;
  let second: string | null;
  try {
    first = fingerprint(observation);
    second = fingerprint(observation);
  } catch {
    return;
  }
  assert.ok(first === null || second === null || first !== second);
}

const database = new PGlite();
try {
  await database.exec('CREATE TABLE protected_probe(id int); INSERT INTO protected_probe VALUES (1); CREATE ROLE ordinary; GRANT SELECT ON protected_probe TO ordinary');
  console.log(JSON.stringify((await database.query('SELECT version()')).rows));
  const adminObservation = await observeEnvironment(database);
  const adminCache = new Map<string, true>();
  await validateSql(database, adminCache);
  await check('unchanged superuser remains reusable', async () => {
    const cache = new Map<string, true>();
    assert.equal((await validateSql(database, cache)).source, 'executed');
    assert.equal((await validateSql(database, cache)).source, 'reused');
    assert.equal(fingerprint(adminObservation), fingerprint(adminObservation));
  });

  await database.exec('SET ROLE ordinary');
  const ordinaryObservation = await observeEnvironment(database);
  console.log(JSON.stringify({ effectiveRole: (await database.query('SELECT current_user, rolsuper FROM pg_roles WHERE rolname=current_user')).rows }));
  const ordinaryCache = new Map<string, true>();
  await validateSql(database, ordinaryCache);
  await check('ordinary role always executes even before a grant change', async () => {
    assert.equal((await validateSql(database, ordinaryCache)).source, 'executed');
  });
  await database.exec('RESET ROLE; REVOKE SELECT ON protected_probe FROM ordinary; SET ROLE ordinary');
  const revokedObservation = await observeEnvironment(database);
  await check('schema and version remain unchanged after revocation', () => {
    assert.equal(ordinaryObservation.schemaDigest, revokedObservation.schemaDigest);
    assert.equal(ordinaryObservation.serverVersion, revokedObservation.serverVersion);
  });
  await check('fresh SQL actually refuses after REVOKE', async () => {
    await assert.rejects(database.query('SELECT count(*) FROM protected_probe'), { code: '42501' });
  });
  await check('cached validation propagates post-revocation SQL refusal', async () => {
    await assert.rejects(validateSql(database, ordinaryCache), { code: '42501' });
    await assert.rejects(validateSql(database, ordinaryCache), { code: '42501' });
  });
  await check('caller-supplied stale administrator observation cannot authorize replay', async () => {
    await assert.rejects(validateSql(database, adminCache, adminObservation), { code: '42501' });
  });
  await check('ordinary observation never authorizes reusable fingerprints', () => {
    noReusableFingerprint({ ...adminObservation, roleSuperuser: false });
  });
  const { roleSuperuser: _, ...missing } = adminObservation;
  await check('missing privilege observation never authorizes reuse', () => noReusableFingerprint(missing));
  for (const roleSuperuser of ['true', null, 1]) {
    await check('invalid privilege observation ' + JSON.stringify(roleSuperuser), () => {
      noReusableFingerprint({ ...adminObservation, roleSuperuser });
    });
  }
  await database.exec('RESET ROLE; CREATE ROLE temporary_admin SUPERUSER; SET ROLE temporary_admin');
  const demotionCache = new Map<string, true>();
  await validateSql(database, demotionCache);
  await database.exec('RESET ROLE; ALTER ROLE temporary_admin NOSUPERUSER; SET ROLE temporary_admin');
  await check('superuser demotion cannot reuse its previous success', async () => {
    await assert.rejects(validateSql(database, demotionCache), { code: '42501' });
  });
} finally {
  await database.close();
}
console.log(JSON.stringify(outcomes, null, 2));
process.exit(outcomes.every(outcome => outcome.pass) ? 0 : 10);
